/** Under reduced motion both requests still wait, so the list and its buttons can be read. */
function restingOf() {
  let state = INITIAL;
  let now = LOADED_AT;
  for (const step of ARRIVAL) {
    now += step.after;
    state = applyAt(state, step.action, now);
  }
  return applyAt(state, { type: 'toggled', id: 'coder' }, now);
}

